const out=[];
for(const el of doc.querySelectorAll('button, a, .link-internal, [data-passage]')){
  const t=(el.textContent||'').trim().slice(0,40);
  const r=el.getBoundingClientRect();
  if(r.width>0&&r.height>0) out.push({t, dp:el.getAttribute('data-passage')||'', x:Math.round(r.x+r.width/2), y:Math.round(r.y+r.height/2)});
}
return JSON.stringify(out.slice(0,30));

